-- Initial PostgreSQL schema. IDs are generated by Prisma; timestamps are UTC.
CREATE TABLE "AdminUser" (
  "id" TEXT NOT NULL,
  "username" TEXT NOT NULL,
  "passwordHash" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "AdminUser_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "AdminSession" (
  "id" TEXT NOT NULL,
  "tokenHash" TEXT NOT NULL,
  "adminId" TEXT NOT NULL,
  "expiresAt" TIMESTAMP(3) NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "AdminSession_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "QuestionPackage" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "description" TEXT NOT NULL DEFAULT '',
  "active" BOOLEAN NOT NULL DEFAULT true,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "QuestionPackage_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Question" (
  "id" TEXT NOT NULL,
  "packageId" TEXT NOT NULL,
  "text" TEXT NOT NULL,
  "options" JSONB NOT NULL,
  "correctAnswer" INTEGER NOT NULL,
  "explanation" TEXT NOT NULL DEFAULT '',
  "imageUrl" TEXT,
  "duration" INTEGER NOT NULL DEFAULT 20,
  "points" INTEGER NOT NULL DEFAULT 100,
  "active" BOOLEAN NOT NULL DEFAULT true,
  "sortOrder" INTEGER NOT NULL DEFAULT 0,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "Question_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "Question_correctAnswer_check" CHECK ("correctAnswer" BETWEEN 0 AND 3),
  CONSTRAINT "Question_duration_check" CHECK ("duration" > 0),
  CONSTRAINT "Question_points_check" CHECK ("points" >= 0),
  CONSTRAINT "Question_options_check" CHECK (jsonb_typeof("options") = 'array' AND jsonb_array_length("options") = 4)
);

CREATE TABLE "Character" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "profession" TEXT NOT NULL,
  "modelPath" TEXT,
  "thumbnailPath" TEXT,
  "animationConfig" JSONB NOT NULL DEFAULT '{}',
  "active" BOOLEAN NOT NULL DEFAULT true,
  CONSTRAINT "Character_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Match" (
  "id" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "packageId" TEXT,
  "packageName" TEXT NOT NULL,
  "teamAName" TEXT NOT NULL DEFAULT 'Tim Emerald',
  "teamBName" TEXT NOT NULL DEFAULT 'Tim Sapphire',
  "phase" TEXT NOT NULL DEFAULT 'WAITING',
  "paused" BOOLEAN NOT NULL DEFAULT false,
  "locked" BOOLEAN NOT NULL DEFAULT false,
  "settings" JSONB NOT NULL,
  "state" JSONB NOT NULL DEFAULT '{}',
  "snapshots" JSONB NOT NULL DEFAULT '[]',
  "ropePosition" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "winner" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "startedAt" TIMESTAMP(3),
  "finishedAt" TIMESTAMP(3),
  CONSTRAINT "Match_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "MatchPlayer" (
  "id" TEXT NOT NULL,
  "matchId" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "team" TEXT NOT NULL,
  "characterId" TEXT NOT NULL,
  "sessionHash" TEXT NOT NULL,
  "connected" BOOLEAN NOT NULL DEFAULT false,
  "ready" BOOLEAN NOT NULL DEFAULT false,
  "correctCount" INTEGER NOT NULL DEFAULT 0,
  "power" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "score" INTEGER NOT NULL DEFAULT 0,
  "answered" BOOLEAN NOT NULL DEFAULT false,
  "joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "MatchPlayer_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "MatchPlayer_team_check" CHECK ("team" IN ('A', 'B'))
);

CREATE TABLE "MatchQuestion" (
  "id" TEXT NOT NULL,
  "matchId" TEXT NOT NULL,
  "sourceQuestionId" TEXT,
  "snapshot" JSONB NOT NULL,
  "questionOrder" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'PENDING',
  "startedAt" TIMESTAMP(3),
  "deadlineAt" TIMESTAMP(3),
  CONSTRAINT "MatchQuestion_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "PlayerAnswer" (
  "id" TEXT NOT NULL,
  "matchId" TEXT NOT NULL,
  "matchQuestionId" TEXT NOT NULL,
  "playerId" TEXT NOT NULL,
  "selectedAnswer" INTEGER NOT NULL,
  "isCorrect" BOOLEAN NOT NULL,
  "pointsAwarded" INTEGER NOT NULL DEFAULT 0,
  "powerAwarded" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "responseTimeMs" INTEGER NOT NULL,
  "submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "PlayerAnswer_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "PlayerAnswer_selectedAnswer_check" CHECK ("selectedAnswer" BETWEEN 0 AND 3),
  CONSTRAINT "PlayerAnswer_responseTimeMs_check" CHECK ("responseTimeMs" >= 0)
);

CREATE TABLE "MatchRound" (
  "id" TEXT NOT NULL,
  "matchId" TEXT NOT NULL,
  "matchQuestionId" TEXT NOT NULL,
  "teamAPower" DOUBLE PRECISION NOT NULL,
  "teamBPower" DOUBLE PRECISION NOT NULL,
  "ropeBefore" DOUBLE PRECISION NOT NULL,
  "ropeAfter" DOUBLE PRECISION NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "MatchRound_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "GameSetting" (
  "id" TEXT NOT NULL DEFAULT 'default',
  "value" JSONB NOT NULL,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "GameSetting_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "AdminUser_username_key" ON "AdminUser"("username");
CREATE UNIQUE INDEX "AdminSession_tokenHash_key" ON "AdminSession"("tokenHash");
CREATE INDEX "AdminSession_expiresAt_idx" ON "AdminSession"("expiresAt");
CREATE INDEX "AdminSession_adminId_idx" ON "AdminSession"("adminId");
CREATE INDEX "Question_packageId_active_sortOrder_idx" ON "Question"("packageId", "active", "sortOrder");
CREATE UNIQUE INDEX "Match_code_key" ON "Match"("code");
CREATE INDEX "Match_phase_createdAt_idx" ON "Match"("phase", "createdAt");
CREATE INDEX "Match_finishedAt_idx" ON "Match"("finishedAt");
CREATE UNIQUE INDEX "MatchPlayer_sessionHash_key" ON "MatchPlayer"("sessionHash");
CREATE INDEX "MatchPlayer_matchId_team_idx" ON "MatchPlayer"("matchId", "team");
CREATE UNIQUE INDEX "MatchQuestion_matchId_questionOrder_key" ON "MatchQuestion"("matchId", "questionOrder");
CREATE UNIQUE INDEX "PlayerAnswer_playerId_matchQuestionId_key" ON "PlayerAnswer"("playerId", "matchQuestionId");
CREATE INDEX "PlayerAnswer_matchId_idx" ON "PlayerAnswer"("matchId");
CREATE UNIQUE INDEX "MatchRound_matchQuestionId_key" ON "MatchRound"("matchQuestionId");
CREATE INDEX "MatchRound_matchId_idx" ON "MatchRound"("matchId");

ALTER TABLE "AdminSession" ADD CONSTRAINT "AdminSession_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Question" ADD CONSTRAINT "Question_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "QuestionPackage"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Match" ADD CONSTRAINT "Match_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "QuestionPackage"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "MatchPlayer" ADD CONSTRAINT "MatchPlayer_matchId_fkey" FOREIGN KEY ("matchId") REFERENCES "Match"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MatchPlayer" ADD CONSTRAINT "MatchPlayer_characterId_fkey" FOREIGN KEY ("characterId") REFERENCES "Character"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "MatchQuestion" ADD CONSTRAINT "MatchQuestion_matchId_fkey" FOREIGN KEY ("matchId") REFERENCES "Match"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MatchQuestion" ADD CONSTRAINT "MatchQuestion_sourceQuestionId_fkey" FOREIGN KEY ("sourceQuestionId") REFERENCES "Question"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "PlayerAnswer" ADD CONSTRAINT "PlayerAnswer_matchId_fkey" FOREIGN KEY ("matchId") REFERENCES "Match"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PlayerAnswer" ADD CONSTRAINT "PlayerAnswer_matchQuestionId_fkey" FOREIGN KEY ("matchQuestionId") REFERENCES "MatchQuestion"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PlayerAnswer" ADD CONSTRAINT "PlayerAnswer_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "MatchPlayer"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MatchRound" ADD CONSTRAINT "MatchRound_matchId_fkey" FOREIGN KEY ("matchId") REFERENCES "Match"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MatchRound" ADD CONSTRAINT "MatchRound_matchQuestionId_fkey" FOREIGN KEY ("matchQuestionId") REFERENCES "MatchQuestion"("id") ON DELETE CASCADE ON UPDATE CASCADE;
